export type ParsedProcessRequestInstruction<
  TProgram extends string = typeof PERP_PRIME_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    signer: TAccountMetas[0];
    config: TAccountMetas[1];
    baseMint: TAccountMetas[2];
    quoteMint: TAccountMetas[3];
    market: TAccountMetas[4];
    requestQueue: TAccountMetas[5];
    eventQueue: TAccountMetas[6];
    bids: TAccountMetas[7];
    asks: TAccountMetas[8];
    openOrdersAccount: TAccountMetas[9];
  };
  data: ProcessRequestInstructionData;
};

export function parseProcessRequestInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedProcessRequestInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    // TODO: Coded error.
    throw new Error('Not enough accounts');
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      signer: getNextAccount(),
      config: getNextAccount(),
      baseMint: getNextAccount(),
      quoteMint: getNextAccount(),
      market: getNextAccount(),
      requestQueue: getNextAccount(),
      eventQueue: getNextAccount(),
      bids: getNextAccount(),
      asks: getNextAccount(),
      openOrdersAccount: getNextAccount(),
    },
    data: getProcessRequestInstructionDataDecoder().decode(instruction.data),
  };
}
